import{_ as i,C as o,o as r,c as s,ai as a,E as p}from"./chunks/framework.hSDj3-GX.js";const e="/OS/assets/image-20260609152351274.Afg8zxOM.png",n="/OS/assets/image-20260609162436709.9EkGhUih.png",d="/OS/assets/image-20260609163138422.BebhdOhN.png",c="/OS/assets/image-20260609164616373.DZE1SyfB.png",g="/OS/assets/image-20260609170352781.D7C8jVxD.png",b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"IO管理/5_3 IO控制方式.md","filePath":"IO管理/5_3 IO控制方式.md","lastUpdated":1781417876000}'),h={name:"IO管理/5_3 IO控制方式.md"};function O(_,t,m,u,I,P){const l=o("QuizSet");return r(),s("div",null,[t[0]||(t[0]=a('<h2 id="i-o控制方式" tabindex="-1">I/O控制方式 <a class="header-anchor" href="#i-o控制方式" aria-label="Permalink to &quot;I/O控制方式&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>I/O控制方式</strong></p><ul><li><strong>程序控制I/O（PIO,Programmed I/O）：</strong>轮询，发出请求后忙等，I/O完成后继续执行</li><li><strong>中断驱动方式（Interrupt-driven I/O）：</strong>I/O结束后由设备通知驱动程序期间别的程序可运行</li><li><strong>直接存储访问方式（DMA, Direct Memory Access）：</strong>用专门的控制器完成内存与设备的数据传输</li><li><strong>通道技术（Channel）：</strong>由一个特殊功能的处理器（通道）负责数据I/O的传输控制，和DMA原理类似</li></ul></div><p>下面以图示方式介绍每种方式的过程，如果能只看图讲清楚流程，那么你就学会了！</p><h3 id="程序控制i-o" tabindex="-1">程序控制I/O <a class="header-anchor" href="#程序控制i-o" aria-label="Permalink to &quot;程序控制I/O&quot;">​</a></h3><p><img src="'+e+'" alt=""></p><p><strong>工作过程：</strong></p><p>① 应用程序发出I/O请求</p><p>② 设备驱动检查设备状态</p><p>③ 设备驱动设置控制寄存器，设备开始工作</p><p>④ 设备驱动不断轮询检查状态寄存器，直到I/O完成，状态修改</p><p>⑤ 设备完成操作，CPU控制传输数据</p><p>⑥ 结束I/O过程，继续执行后续程序</p><hr><h3 id="中断驱动" tabindex="-1">中断驱动 <a class="header-anchor" href="#中断驱动" aria-label="Permalink to &quot;中断驱动&quot;">​</a></h3><p><img src="'+n+'" alt=""></p><p><strong>工作过程：</strong></p><p>① 应用程序发出I/O请求</p><p>② 设备驱动检查设备状态</p><p>③ 设备驱动设置控制寄存器，设备开始工作</p><p>④ 将设备状态记录在表，CPU执行其他工作</p><p>⑤ 设备完成操作，发出中断信号，转入中断处理</p><p>⑥ 中断处理检查信号正常，交接给设备管理程序</p><p>⑦ 设备管理程序从表中查询相关信息</p><p>⑧ CPU控制传输数据</p><p>⑨ 通知应用程序可继续进行</p><hr><h3 id="直接存储访问" tabindex="-1">直接存储访问 <a class="header-anchor" href="#直接存储访问" aria-label="Permalink to &quot;直接存储访问&quot;">​</a></h3><p><img src="'+d+'" alt=""></p><p><strong>工作过程：</strong></p><ol><li><p>由程序设置DMA控制器中的若干寄存器值（如内存始址，传送字节数），然后发起I/O操作；</p></li><li><p>DMA控制器完成内存与外设的成批数据交换；</p></li><li><p>在<strong>操作完成时</strong>由DMA控制器向CPU发出中断。</p></li></ol><p><strong>寄存器含义：</strong></p><ul><li>DR：暂存数据</li><li>DC：记录读写数据的量</li><li>MAR：记录要写入（或写出）的数据内存地址</li><li>CR：设置状态，或反映当前状态</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><p>DMA流程上和中断方式有点像，主要区别如下：</p><ol><li><strong>单位不同：</strong>中断方式在每个单位数据传送完成就发出中断信号，DMA则为一批</li><li><strong>CPU干预程度不同：</strong>中断方式的数据传输由CPU控制，而DMA只在传输完通知CPU</li><li><strong>处理异常的能力：</strong>中断方式有处理异常事件能力，DMA较死板，适合数据块传输</li></ol></div><hr><h3 id="i-o通道控制" tabindex="-1">I/O通道控制 <a class="header-anchor" href="#i-o通道控制" aria-label="Permalink to &quot;I/O通道控制&quot;">​</a></h3><p><strong>基本思想：</strong>进一步减少CPU干预</p><p><img src="'+c+'" alt=""></p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><p>I/O通道和DMA有如下区别：</p><ol><li><strong>CPU干预程度不同：</strong>DMA需要CPU去设置数据传输方向、存放数据的内存地址和数据块长度等参数；而通道技术把这些写在通道程序里面让通道处理器执行即可</li><li><strong>并发性不同：</strong>DMA只能控制一台或少数几台同类设备；而一个通道可控制多种设备</li></ol><p>DMA像自动化机器。机器会自己完成数据搬运，但你仍需要亲自接通、设置地址和长度、选择模式并启动。</p><p>当设备很多、任务复杂时，CPU如果还要逐项配置，仍会浪费不少时间。</p><p>通道则像专门负责操作这些机器的员工。CPU只需准备一份通道程序并启动通道，通道就会按计划控制设备、完成多次传输，最后再通知CPU。</p></div><p><img src="'+g+'" alt=""></p><p><strong>通道分类：</strong></p><ul><li><strong>字节多路通道：</strong><ul><li>以字节为单位交叉工作：</li><li>当为一台设备传送一个字节后，立即转去为另一它设备传送一个字节；</li><li>适用于连接打印机、终端等低速或中速的I/O设备。</li></ul></li><li><strong>数组选择通道：</strong><ul><li>以“组方式”工作，每次传送一批数据，传送速率很高，但在一段时间只能为一台设备服务。每当一个I/O请求处理完之后，就选择另一台设备并为其服务；</li><li>适用于连接磁盘、磁带等高速设备。</li></ul></li><li><strong>数组多路通道</strong><ul><li>综合了字节多路通道分时工作和选择通道传输速率高的特点；</li><li>其实质是：对通道程序采用多道程序设计技术，使得与通道连接的设备可以并行工作。</li></ul></li></ul><hr><table tabindex="0"><thead><tr><th>方式</th><th>核心</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>程序控制I/O</td><td>CPU轮询直到I/O完成</td><td>简单</td><td>CPU占用时间很长</td></tr><tr><td>中断处理</td><td>可执行其他程序直到I/O完成发出中断信号才处理</td><td>1. 减少轮询占用CPU的时间<br>2. 可灵活处理异常事件</td><td>CPU占用时间较长</td></tr><tr><td>DMA</td><td>由专门DMA控制器完成数据传输，只需开始时设置寄存器、结束时唤醒</td><td>CPU只干预I/O开始和结束后续成批数据无需CPU，适合高速设备</td><td>1.数据方向、存放数据的内存地址、数据量等由CPU控制，占用时间<br>2.每个设备需要相应的DMA资源，设备增加时需增加DMA</td></tr><tr><td>通道</td><td>由专门的通道处理器根据给定的通道程序执行完成I/O</td><td>执行一个通道程序可以完成几组I/O操作，减少CPU干预</td><td>费用较高</td></tr></tbody></table><p>从上至下是不断将I/O从CPU解耦到其他模块的过程，CPU干预程度不断下降，但硬件层也变复杂，成本升高</p><h2 id="复习题" tabindex="-1">复习题 <a class="header-anchor" href="#复习题" aria-label="Permalink to &quot;复习题&quot;">​</a></h2>',45)),p(l,{collection:"final-review"})])}const D=i(h,[["render",O]]);export{b as __pageData,D as default};
